// 1. Pega os dados do CSV do nó "Consultar csv"
const csvItem = $('Consultar dados csv').first();
const csvString = csvItem.json.data || csvItem.json.body || '';

// 2. Processa o CSV limpando espaços e quebras de linha
const lines = csvString.replace(/\r/g, '').trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().toLowerCase());

const produtos = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const currentLine = line.split(',');
  const obj = {};
  for (let j = 0; j < headers.length; j++) {
    obj[headers[j]] = currentLine[j] ? currentLine[j].trim() : '';
  }
  produtos.push(obj);
}

// 3. Captura os clientes considerando o .body do Webhook do n8n
let clientes = [];
const webhookItems = $('Receber dados clientes').all();
for (const item of webhookItems) {
  // O n8n guarda o JSON enviado pelo POST dentro de .body ou diretamente em .json
  const payload = item.json.body || item.json;
  const listaClientes = payload.clientes || payload.Clientes;

  if (listaClientes && Array.isArray(listaClientes)) {
    clientes = clientes.concat(listaClientes);
  } else if (Array.isArray(payload)) {
    clientes = clientes.concat(payload);
  } else if (payload.perfil) {
    clientes.push(payload);
  }
}

// Fallback de segurança caso o webhook venha vazio por algum motivo de teste
if (clientes.length === 0) {
  clientes = [
    { nome: "Ana Silva", email: "ana@email.com", saldo: "R$ 12.500,00", perfil: "Conservador" },
    { nome: "Bruno Lima", email: "bruno@email.com", saldo: "R$ 3.200,00", perfil: "Moderado" },
    { nome: "Carla Souza", email: "carla@email.com", saldo: "R$ 28.900,00", perfil: "Arrojado" }
  ];
}

// 4. Faz o cruzamento por perfil ignorando maiúsculas/minúsculas
const resultado = clientes.map(cliente => {
  const perfilCliente = (cliente.perfil || '').toString().trim().toLowerCase();

  const recomendacoes = produtos.filter(p => {
    const perfilProduto = (p.perfil || '').toString().trim().toLowerCase();
    return perfilProduto === perfilCliente;
  });

  const autor = "J84dev";

  return {
    json: {
      nome: cliente.nome || '',
      email: cliente.email || '',
      saldo: cliente.saldo || '',
      perfil: cliente.perfil || '',
      recomendacoes: recomendacoes
    }
  };
});

return resultado;

